import{getBunServer}from"./server.js";var getConnInfo=e=>{const r=getBunServer(e);if(!r)throw new TypeError("env has to include the 2nd argument of fetch.");if("function"!=typeof r.requestIP)throw new TypeError("server.requestIP is not a function.");const t=r.requestIP(e.req.raw);return t?{remote:{address:t.address,addressType:"IPv6"===t.family||"IPv4"===t.family?t.family:void 0,port:t.port}}:{remote:{}}};export{getConnInfo};